BEGIN;
RESET ROLE;
SET LOCAL request.jwt.claim.sub = '';
SELECT harness.try_dml('HO archives class K', $dml$UPDATE public.classes SET archived_at = now(), archived_by_user_id = '1a000000-0000-0000-0000-000000000001', archive_reason = 'HO closed class' WHERE id = '4a000000-0000-0000-0000-000000000001' RETURNING id$dml$);
SET LOCAL ROLE authenticated;
SET LOCAL request.jwt.claim.sub = '1a000000-0000-0000-0000-000000000002';
SELECT harness.try_dml('EA_A class membership C_FREE->K (merge upsert)', $dml$INSERT INTO public.child_class_memberships (id, child_id, class_id, academic_year_id, enrolled_at, created_by, row_version) VALUES ('9a000000-0000-0000-0000-000000000020', '5a000000-0000-0000-0000-000000000005', '4a000000-0000-0000-0000-000000000001', (SELECT id FROM public.academic_years WHERE is_active), now(), '1a000000-0000-0000-0000-000000000002', '2') ON CONFLICT (id) DO UPDATE SET child_id = EXCLUDED.child_id, class_id = EXCLUDED.class_id, academic_year_id = EXCLUDED.academic_year_id, enrolled_at = EXCLUDED.enrolled_at, created_by = EXCLUDED.created_by, row_version = EXCLUDED.row_version RETURNING id$dml$);
SELECT harness.try_dml('EA_A session for class K (insert-or-ignore)', $dml$INSERT INTO public.sessions (id, user_id, programme_id, class_id, session_date) VALUES ('86000000-0000-0000-0000-000000000001', '1a000000-0000-0000-0000-000000000002', (SELECT id FROM public.programmes WHERE code = 'literacy'), '4a000000-0000-0000-0000-000000000001', '2026-11-04') ON CONFLICT (id) DO NOTHING RETURNING id$dml$);
SELECT harness.try_dml('EA_A group in class K (merge upsert)', $dml$INSERT INTO public.groups (id, name, programme_id, class_id, created_by, row_version) VALUES ('7a000000-0000-0000-0000-000000000020', 'New group in archived class', (SELECT id FROM public.programmes WHERE code = 'literacy'), '4a000000-0000-0000-0000-000000000001', '1a000000-0000-0000-0000-000000000002', '2') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, programme_id = EXCLUDED.programme_id, class_id = EXCLUDED.class_id, created_by = EXCLUDED.created_by, row_version = EXCLUDED.row_version RETURNING id$dml$);
SELECT harness.try_dml('EA_A child in class K (merge upsert)', $dml$INSERT INTO public.children (id, first_name, last_name, class_id, created_by, row_version) VALUES ('5a000000-0000-0000-0000-000000000020', 'New', 'Child', '4a000000-0000-0000-0000-000000000001', '1a000000-0000-0000-0000-000000000002', '2') ON CONFLICT (id) DO UPDATE SET first_name = EXCLUDED.first_name, last_name = EXCLUDED.last_name, class_id = EXCLUDED.class_id, created_by = EXCLUDED.created_by, row_version = EXCLUDED.row_version RETURNING id$dml$);
SELECT harness.try_dml('EA_A edits archived class K name (UPDATE by id)', $dml$UPDATE public.classes SET name = 'renamed after archive', row_version = 2 WHERE id = '4a000000-0000-0000-0000-000000000001' RETURNING id$dml$);
SET LOCAL ROLE authenticated;
SET LOCAL request.jwt.claim.sub = '1a000000-0000-0000-0000-000000000003';
SELECT harness.try_dml('EA_B class_ea_assignment into archived K (insert-or-ignore)', $dml$INSERT INTO public.class_ea_assignments (id, class_id, ea_user_id, programme_id, created_by) VALUES ('622c4d00-7c02-538b-9c10-576eacb1c6ab', '4a000000-0000-0000-0000-000000000001', '1a000000-0000-0000-0000-000000000003', (SELECT id FROM public.programmes WHERE code = 'literacy'), '1a000000-0000-0000-0000-000000000003') ON CONFLICT (id) DO NOTHING RETURNING id$dml$);
ROLLBACK;
